def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != 0]

    # Identify the coordinate that stays constant along the colored stripes.
    candidates = [
        (lambda r, c: r, "row"),
        (lambda r, c: c, "col"),
        (lambda r, c: c-r, "diff"),
        (lambda r, c: r+c, "sum"),
    ]
    best = None
    for coord, name in candidates:
        counts = {}
        for r, c, _ in points:
            k = coord(r, c)
            counts[k] = counts.get(k, 0) + 1
        score = max(counts.values(), default=0)
        if best is None or score > best[0]:
            best = (score, name, coord, counts)

    _, name, coord, _ = best
    stripes = {}
    for r, c, color in points:
        stripes[coord(r, c)] = color

    # Recover the repeating stripe pattern; colors on equal residues must agree.
    for p in range(1, h + w + 1):
        pattern = {}
        valid = True
        for k, color in stripes.items():
            residue = k % p
            if residue in pattern and pattern[residue] != color:
                valid = False
                break
            pattern[residue] = color
        if valid and len(pattern) > 1:
            break

    return [[pattern[(coord(r, c)) % p] for c in range(w)] for r in range(h)]
